def parse_sep(s):
    try:
        # Use unicode_escape if backslash present
        if "\\" in s:
            return bytes(s, "utf-8").decode("unicode_escape")
        return s
    except:
        return s

def is_numeric_type(col_type):
    if not col_type:
        return False
    t = col_type.lower()
    for kw in ["int", "decimal", "numeric", "double", "float", "real", "number"]:
        if kw in t:
            return True
    return False

def format_duckbox(columns, rows):
    col_widths=[]
    str_rows=[]
    for r in rows:
        str_rows.append([str(x) for x in r])
    for i, (col_name, col_type) in enumerate(columns):
        max_len = len(col_name)
        max_len = max(max_len, len(col_type))
        for sr in str_rows:
            if i < len(sr):
                max_len = max(max_len, len(sr[i]))
        width = max_len + 2
        col_widths.append(width)
    out_lines=[]
    top = "┌"
    for idx, w in enumerate(col_widths):
        top += "─"*w
        if idx < len(col_widths)-1:
            top += "┬"
        else:
            top += "┐"
    out_lines.append(top)
    header_line = "│"
    for idx, (col_name, _) in enumerate(columns):
        w = col_widths[idx]
        centered = col_name.center(w)
        header_line += centered + "│"
    out_lines.append(header_line)
    type_line = "│"
    for idx, (_, col_type) in enumerate(columns):
        w = col_widths[idx]
        centered = col_type.center(w)
        type_line += centered + "│"
    out_lines.append(type_line)
    sep_line = "├"
    for idx, w in enumerate(col_widths):
        sep_line += "─"*w
        if idx < len(col_widths)-1:
            sep_line += "┼"
        else:
            sep_line += "┤"
    out_lines.append(sep_line)
    for sr in str_rows:
        row_line = "│"
        for idx, val_str in enumerate(sr):
            w = col_widths[idx]
            col_type = columns[idx][1]
            if is_numeric_type(col_type):
                aligned = val_str.rjust(w-1) + " "
            else:
                aligned = " " + val_str.ljust(w-1)
            row_line += aligned + "│"
        out_lines.append(row_line)
    bottom = "└"
    for idx, w in enumerate(col_widths):
        bottom += "─"*w
        if idx < len(col_widths)-1:
            bottom += "┴"
        else:
            bottom += "┘"
    out_lines.append(bottom)
    return "\n".join(out_lines) + "\n"

