            out+=f"│{tbl_name.center(width)}│\n"
            out+=f"│{' '*width}│\n"
            for cs in col_strs:
                out+=f"│{' '+cs.ljust(width-1)}│\n"
            out+=f"│{' '*width}│\n"
            out+=f"│{row_str.center(width)}│\n"
            out+=f"└{'─'*width}┘\n"
        return out, False, False

    if cmd == "schema":
        if len(args)>1:
            return f"Invalid Command Error: Invalid usage of command '.schema'\n\nUsage: '.schema ?PATTERN?'\n", True, False
        pat=args[0] if args else None
        cur=state.db.conn.cursor()
        if pat:
            cur.execute("SELECT sql FROM sqlite_master WHERE type='table' AND name LIKE ?", (pat,))
        else:
            cur.execute("SELECT sql FROM sqlite_master WHERE type='table'")
        out=""
        for r in cur.fetchall():
            sql=r[0]
            if sql:
                out+=sql+";\n"
        return out, False, False

    if cmd == "databases":
        if args:
            return f"Invalid Command Error: Invalid usage of command '.databases'\n\nUsage: '.databases '\n", True, False
        dbs=state.db.get_databases()
        # Produce colored box similar to original
        GRAY="\x1b[90m"
        RESET="\x1b[00m"
        BOLD="\x1b[1m"
        header="databases"
        entries=[f"{name} {path}" for name,path in dbs]
        max_len=len(header)
        for e in entries:
            max_len=max(max_len, len(e))
        width=max_len+2
        lines=[]
        lines.append(f"{GRAY}┌{'─'*width}┐{RESET}{GRAY}")
        leading=(width-len(header))//2
        trailing=width-len(header)-leading
        lines.append(f"{GRAY}│{' '*leading}{RESET}{BOLD}{header}{RESET}{GRAY}{' '*trailing}│{RESET}{GRAY}")
        lines.append(f"{GRAY}│{' '*width}│{RESET}{GRAY}")
        for entry in entries:
            padded=f" {entry} ".ljust(width)
            lines.append(f"{GRAY}│{RESET}{padded}{GRAY}│{RESET}{GRAY}")
        lines.append(f"{GRAY}└{'─'*width}┘{RESET}{GRAY}")
        lines.append(f"{RESET}")
        return "\n".join(lines)+"\n", False, False

    if cmd == "dump":
        pat=None
        for a in args:
            if a.startswith('--'):
                continue
            else:
                pat=a
        cur=state.db.conn.cursor()
        if pat:
            cur.execute("SELECT name, sql FROM sqlite_master WHERE type='table' AND name LIKE ?", (pat,))
        else:
            cur.execute("SELECT name, sql FROM sqlite_master WHERE type='table'")
        tables=cur.fetchall()
        out="BEGIN TRANSACTION;\n"
        for name, sql in tables:
            if sql:
                out+=sql+";;\n"
            try:
                cur2=state.db.conn.cursor()
                cur2.execute(f'SELECT * FROM "{name}"')
                rows=cur2.fetchall()
                for r in rows:
                    vals=[]
                    for v in r:
                        if v is None:
                            vals.append("NULL")
                        elif isinstance(v,int):
                            vals.append(str(v))
                        elif isinstance(v,float):
                            vals.append(str(v))
                        else:
                            s=str(v).replace("'", "''")
                            vals.append(f"'{s}'")
                    out+=f'INSERT INTO main.{name} VALUES({",".join(vals)});\n'
            except:
                pass
        out+="COMMIT;\n"
        return out, False, False

    if cmd == "import":
        if len(args)<2:
            return f"ERROR: missing TABLE argument. Usage:\n\x1b[32m.import\x1b[00m\x1b[33m FILE TABLE\x1b[00m                       Import data from FILE into TABLE\n  Options:\n\x1b[33m    --csv\x1b[00m                    Import data from CSV (read_csv)\n", True, False
        table=args[-1]
        file_path=args[-2]
        if not os.path.exists(file_path):
            return f"Failed To Import Error: Failed to import from file '{file_path}'\n\nIO Error: No files found that match the pattern \"{file_path}\"\n\nLINE 1: CREATE TABLE \"{table}\" AS SELECT * FROM read_csv('{file_path}', ignore_errors='true')\n                                              ^\n", True, False
        try:
            with open(file_path, newline='', encoding='utf-8') as f:
                reader=csv.reader(f)
                header=next(reader)
                rows=list(reader)
            cur=state.db.conn.cursor()
            cur.execute("SELECT name FROM sqlite_master WHERE type='table' AND name=?", (table,))
            exists=cur.fetchone()
            if not exists:
                cols_def=", ".join([f'"{col}" TEXT' for col in header])
                cur.execute(f'CREATE TABLE "{table}" ({cols_def})')
            placeholders=", ".join(["?" for _ in header])
            cols_list=", ".join([f'"{c}"' for c in header])
            for row in rows:
                if len(row)<len(header):
                    row=row+[""]*(len(header)-len(row))
                elif len(row)>len(header):
                    row=row[:len(header)]
                cur.execute(f'INSERT INTO "{table}" ({cols_list}) VALUES ({placeholders})', row)
            state.db.conn.commit()
            return "", False, False
        except Exception as e:
            return f"Failed To Import Error: {e}\n", True, False

    if cmd in ("shell","system"):
        idx=line.lower().find(cmd)
        rest=line[idx+len(cmd):].strip()
        if not rest:
            return "", False, False
        try:
            result=subprocess.run(rest, shell=True, capture_output=True, text=True, timeout=10)
            return result.stdout, False, False
        except Exception as e:
