    for sql in sql_positional:
        if sql.startswith('.'):
            result, is_error, is_read = handle_dot_command(shell, sql)
            if isinstance(result, str) and result.startswith("__READ_FILE__:"):
                fp=result.split(":",1)[1]
                try:
