            if had_err:
                had_error=True
                if shell.bail:
                    break

    has_batch=len(state_opts["c_cmds"])>0 or len(state_opts["f_files"])>0 or len(sql_positional)>0
    if not has_batch and not state_opts["no_stdin"]:
        is_tty=sys.stdin.isatty()
        if state_opts["interactive"] or is_tty:
