            sys.stdout.write("\x1b[90mEnter \".help\" for usage hints.\n\x1b[00m")
        stdin_content=sys.stdin.read()
        if stdin_content.strip()!="":
            err=process_input(shell, stdin_content, output_handle=sys.stdout, is_file=False)
            if err:
                had_error=True

    sys.exit(1 if had_error else 0)

if __name__=="__main__":
    main()
