                max_len = max(max_len, len(sr[i]))
        width = max_len + 2
        col_widths.append(width)
    out_lines=[]
    top = "┌"
    for idx, w in enumerate(col_widths):
        top += "─"*w
        if idx < len(col_widths)-1:
            top += "┬"
        else:
            top += "┐"
    out_lines.append(top)
    header_line = "│"
    for idx, (col_name, _) in enumerate(columns):
        w = col_widths[idx]
        centered = col_name.center(w)
        header_line += centered + "│"
    out_lines.append(header_line)
    type_line = "│"
    for idx, (_, col_type) in enumerate(columns):
        w = col_widths[idx]
        centered = col_type.center(w)
        type_line += centered + "│"
