        if idx < len(col_widths)-1:
            sep_line += "┼"
        else:
            sep_line += "┤"
    out_lines.append(sep_line)
    for sr in str_rows:
        row_line = "│"
        for idx, val_str in enumerate(sr):
            w = col_widths[idx]
            col_type = columns[idx][1]
            if is_numeric_type(col_type):
                aligned = val_str.rjust(w-1) + " "
            else:
                aligned = " " + val_str.ljust(w-1)
            row_line += aligned + "│"
        out_lines.append(row_line)
    bottom = "└"
    for idx, w in enumerate(col_widths):
        bottom += "─"*w
        if idx < len(col_widths)-1:
            bottom += "┴"
        else:
            bottom += "┘"
    out_lines.append(bottom)
    return "\n".join(out_lines) + "\n"

