def levenshtein(a,b):
    n=len(a); m=len(b)
    dp=[[0]*(m+1) for _ in range(n+1)]
    for i in range(n+1):
        dp[i][0]=i
    for j in range(m+1):
        dp[0][j]=j
    for i in range(1,n+1):
        for j in range(1,m+1):
            cost=0 if a[i-1]==b[j-1] else 1
            dp[i][j]=min(dp[i-1][j]+1, dp[i][j-1]+1, dp[i-1][j-1]+cost)
    return dp[n][m]

def suggest_options(unk):
    if unk in HARDCODED_SUGGESTIONS:
        return HARDCODED_SUGGESTIONS[unk]
    distances=[]
    for v in valid_opts:
        d=levenshtein(unk, v)
        distances.append((d, v))
    distances.sort(key=lambda x: (x[0], x[1]))
    candidates=[]
    if distances:
        min_dist=distances[0][0]
        if min_dist <=3:
            for d,v in distances:
                if d<=3:
                    candidates.append(v)
                if len(candidates)>=5:
                    break
        else:
            candidates=[v for d,v in distances[:5]]
    if not candidates:
        return ""
    return ", ".join(f'"{c}"' for c in candidates[:5])

def print_help(prog_name):
    BOLD="\x1b[1m"; RESET="\x1b[00m"; GREEN="\x1b[32m"; YELLOW="\x1b[33m"
    out = f"{BOLD}Usage: {RESET}{GREEN}{prog_name}{RESET}{YELLOW} [OPTIONS] FILENAME [SQL]\n\n"
    out += f"{RESET}{BOLD}FILENAME{RESET} is the name of a DuckDB database. A new database is created\n"
    out += f"if the file does not previously exist.\n\n"
    out += f"{BOLD}OPTIONS:\n{RESET}"
    for flag, arg, desc in options_order:
        if arg is None:
            opt_str=f"  {flag}"
            out+=f"{GREEN}{opt_str}{RESET}{' '*(27-len(opt_str))}{desc}\n"
        else:
            opt_str=f"  {flag}"
            arg_str=f" {arg}"
            out+=f"{GREEN}{opt_str}{RESET}{YELLOW}{arg_str}{RESET}{' '*(27-len(opt_str+arg_str))}{desc}\n"
    sys.stdout.write(out)

def print_unknown_option(prog_name, opt):
    suggestion=suggest_options(opt)
    sys.stderr.write(f"Unknown Option Error: Unrecognized option '{opt}'\n\n")
    if suggestion:
        sys.stderr.write(f"Did you mean: {suggestion}\n")
    sys.stderr.write(f"Run '{prog_name} -help' for a list of options.\n\n")

def print_missing_arg(prog_name, opt):
    _, arg_name, desc = opt_info.get(opt, (True, "ARG", ""))
    opt_line=f"  {opt} {arg_name}    {desc}" if arg_name else f"  {opt}    {desc}"
    sys.stderr.write(f"Missing Argument Error: Argument '{opt}' needs 1 arguments, but got 0\n")
    sys.stderr.write("OPTION:\n")
    sys.stderr.write(f"{opt_line}\n\n")
    sys.stderr.write(f"Run '{prog_name} -help' for a list of options.\n\n")

def parse_sep(s):
    try:
        if "\\" in s:
            return bytes(s, "utf-8").decode("unicode_escape")
        return s
    except:
        return s

def is_numeric_type(col_type):
    if not col_type:
        return False
    t=col_type.lower()
    for kw in ["int","decimal","numeric","double","float","real","number"]:
        if kw in t:
            return True
    return False

def format_duckbox(columns, rows):
    col_widths=[]
    str_rows=[[str(x) for x in r] for r in rows]
    for i,(col_name,col_type) in enumerate(columns):
        max_len=len(col_name)
        max_len=max(max_len, len(col_type))
        for sr in str_rows:
            if i < len(sr):
                max_len=max(max_len, len(sr[i]))
        col_widths.append(max_len+2)
    out=[]
    top="┌"
    for idx,w in enumerate(col_widths):
        top+="─"*w
        top+="┬" if idx < len(col_widths)-1 else "┐"
    out.append(top)
    header_line="│"
    for idx,(col_name,_) in enumerate(columns):
        header_line+=col_name.center(col_widths[idx])+"│"
    out.append(header_line)
    type_line="│"
    for idx,(_,col_type) in enumerate(columns):
        type_line+=col_type.center(col_widths[idx])+"│"
    out.append(type_line)
    sep_line="├"
    for idx,w in enumerate(col_widths):
        sep_line+="─"*w
        sep_line+="┼" if idx < len(col_widths)-1 else "┤"
    out.append(sep_line)
    for sr in str_rows:
        row_line="│"
        for idx,val_str in enumerate(sr):
            w=col_widths[idx]
            col_type=columns[idx][1]
            if is_numeric_type(col_type):
                aligned=val_str.rjust(w-1)+" "
            else:
                aligned=" "+val_str.ljust(w-1)
            row_line+=aligned+"│"
        out.append(row_line)
    bottom="└"
    for idx,w in enumerate(col_widths):
        bottom+="─"*w
        bottom+="┴" if idx < len(col_widths)-1 else "┘"
    out.append(bottom)
    return "\n".join(out)+"\n"

