def levenshtein(a,b):
    n=len(a); m=len(b)
    dp=[[0]*(m+1) for _ in range(n+1)]
    for i in range(n+1):
        dp[i][0]=i
    for j in range(m+1):
        dp[0][j]=j
    for i in range(1,n+1):
        for j in range(1,m+1):
            cost=0 if a[i-1]==b[j-1] else 1
            dp[i][j]=min(dp[i-1][j]+1, dp[i][j-1]+1, dp[i-1][j-1]+cost)
    return dp[n][m]

def suggest_options(unk):
    if unk in HARDCODED_SUGGESTIONS:
        return HARDCODED_SUGGESTIONS[unk]
    distances=[]
    for v in valid_opts:
        d=levenshtein(unk, v)
        distances.append((d, v))
    distances.sort(key=lambda x: (x[0], x[1]))
    candidates=[]
    if distances:
        min_dist=distances[0][0]
        if min_dist <=3:
            for d,v in distances:
                if d<=3:
                    candidates.append(v)
                if len(candidates)>=5:
                    break
        else:
            candidates=[v for d,v in distances[:5]]
    if not candidates:
        return ""
    return ", ".join(f'"{c}"' for c in candidates[:5])

def print_help(prog_name):
    BOLD="\x1b[1m"; RESET="\x1b[00m"; GREEN="\x1b[32m"; YELLOW="\x1b[33m"
    out = f"{BOLD}Usage: {RESET}{GREEN}{prog_name}{RESET}{YELLOW} [OPTIONS] FILENAME [SQL]\n\n"
    out += f"{RESET}{BOLD}FILENAME{RESET} is the name of a DuckDB database. A new database is created\n"
    out += f"if the file does not previously exist.\n\n"
    out += f"{BOLD}OPTIONS:\n{RESET}"
    for flag, arg, desc in options_order:
        if arg is None:
            opt_str=f"  {flag}"
            out+=f"{GREEN}{opt_str}{RESET}{' '*(27-len(opt_str))}{desc}\n"
        else:
            opt_str=f"  {flag}"
            arg_str=f" {arg}"
            out+=f"{GREEN}{opt_str}{RESET}{YELLOW}{arg_str}{RESET}{' '*(27-len(opt_str+arg_str))}{desc}\n"
    sys.stdout.write(out)

def print_unknown_option(prog_name, opt):
