        if kw in t:
            return True
    return False

def format_duckbox(columns, rows):
    col_widths=[]
    str_rows=[[str(x) for x in r] for r in rows]
    for i,(col_name,col_type) in enumerate(columns):
        max_len=len(col_name)
        max_len=max(max_len, len(col_type))
        for sr in str_rows:
            if i < len(sr):
                max_len=max(max_len, len(sr[i]))
        col_widths.append(max_len+2)
    out=[]
    top="┌"
    for idx,w in enumerate(col_widths):
        top+="─"*w
        top+="┬" if idx < len(col_widths)-1 else "┐"
    out.append(top)
    header_line="│"
    for idx,(col_name,_) in enumerate(columns):
        header_line+=col_name.center(col_widths[idx])+"│"
    out.append(header_line)
    type_line="│"
    for idx,(_,col_type) in enumerate(columns):
        type_line+=col_type.center(col_widths[idx])+"│"
    out.append(type_line)
    sep_line="├"
    for idx,w in enumerate(col_widths):
        sep_line+="─"*w
        sep_line+="┼" if idx < len(col_widths)-1 else "┤"
    out.append(sep_line)
    for sr in str_rows:
        row_line="│"
        for idx,val_str in enumerate(sr):
            w=col_widths[idx]
            col_type=columns[idx][1]
            if is_numeric_type(col_type):
                aligned=val_str.rjust(w-1)+" "
            else:
                aligned=" "+val_str.ljust(w-1)
            row_line+=aligned+"│"
        out.append(row_line)
    bottom="└"
    for idx,w in enumerate(col_widths):
        bottom+="─"*w
        bottom+="┴" if idx < len(col_widths)-1 else "┘"
    out.append(bottom)
    return "\n".join(out)+"\n"

def format_box(columns, rows):
