def format_column(columns, rows):
    col_widths=[]
    str_rows=[[str(x) for x in r] for r in rows]
    for i,(col_name,_) in enumerate(columns):
        max_len=len(col_name)
        for sr in str_rows:
            if i < len(sr):
                max_len=max(max_len, len(sr[i]))
        col_widths.append(max_len)
    out_lines=[]
    header_parts=[col_name.ljust(w) for (col_name,_),w in zip(columns, col_widths)]
    out_lines.append("  ".join(header_parts))
    dash_parts=["-"*w for w in col_widths]
    out_lines.append("  ".join(dash_parts))
    for sr in str_rows:
        out_lines.append("  ".join([val_str.ljust(w) for val_str,w in zip(sr, col_widths)]))
    return "\n".join(out_lines)+"\n" if out_lines else ""

def format_csv(columns, rows, header=True, sep=",", newline="\n", nullvalue="NULL"):
    output=io.StringIO()
    writer=csv.writer(output, quoting=csv.QUOTE_MINIMAL, lineterminator=newline, delimiter=sep, quotechar='"', doublequote=True)
    if header:
        writer.writerow([c[0] for c in columns])
    for r in rows:
        row_out=[]
        for v in r:
            if v is None:
                row_out.append(nullvalue)
            else:
                row_out.append(str(v))
        writer.writerow(row_out)
    return output.getvalue()

def format_list(columns, rows, header=True, sep="|", newline="\n", nullvalue="NULL"):
    out=""
    if header:
        out+=sep.join([c[0] for c in columns])+newline
    for r in rows:
        out+=sep.join([nullvalue if v is None else str(v) for v in r])+newline
    return out

def format_markdown(columns, rows, nullvalue="NULL"):
    disp=[[nullvalue if v is None else v for v in r] for r in rows]
    str_rows=[[str(x) for x in row] for row in disp]
    col_widths=[]
    for i,(col_name,_) in enumerate(columns):
        max_len=len(col_name)
        for sr in str_rows:
            if i < len(sr):
                max_len=max(max_len, len(sr[i]))
        col_widths.append(max_len)
    header_line="| " + " | ".join([c[0] for c in columns]) + " |"
    sep_parts=[]
    for (col_name,col_type), w in zip(columns, col_widths):
        dash_len=max(3,w)
        if is_numeric_type(col_type):
            sep_parts.append("-"*(dash_len-1) + ":")
        else:
            sep_parts.append("-"*dash_len)
    sep_line="|" + "|".join(sep_parts) + "|"
    out_lines=[header_line, sep_line]
    for sr in str_rows:
        out_lines.append("| " + " | ".join(sr) + " |")
    return "\n".join(out_lines)+"\n"

def format_html(columns, rows, header=True, nullvalue="NULL"):
    out_lines=[]
    if header and columns:
        out_lines.append(f"<tr><th>{columns[0][0]}</th>")
        for col_name,_ in columns[1:]:
            out_lines.append(f"<th>{col_name}</th>")
        out_lines.append("</tr>")
    for r in rows:
        vals=[nullvalue if v is None else str(v) for v in r]
        if not vals:
            continue
        out_lines.append(f"<tr><td>{vals[0]}</td>")
        for v in vals[1:]:
            out_lines.append(f"<td>{v}</td>")
        out_lines.append("</tr>")
    return "\n".join(out_lines)+"\n" if out_lines else ""

def format_line(columns, rows, nullvalue="NULL"):
    out=""
    for idx,r in enumerate(rows):
        for (col_name,_), v in zip(columns, r):
            val_str=nullvalue if v is None else str(v)
            out+=f"{col_name:>8} = {val_str}\n"
        if idx < len(rows)-1:
            out+="\n"
    return out

def format_ascii(columns, rows, header=True, nullvalue="NULL"):
    out=""
    if header:
        for col_name,_ in columns:
            out+=col_name+"\n"
    for r in rows:
        for v in r:
            out+=(nullvalue if v is None else str(v))+"\n"
    return out

def format_quote(columns, rows, header=True, sep=",", newline="\n", nullvalue="NULL"):
    out=""
    if header:
        hdr=[]
        for col_name,_ in columns:
            esc=col_name.replace("'", "''")
            hdr.append(f"'{esc}'")
        out+=sep.join(hdr)+newline
    for r in rows:
        vals=[]
        for v in r:
            if v is None:
                vals.append(nullvalue)
            elif isinstance(v,int) or isinstance(v,float):
                vals.append(str(v))
            else:
                s=str(v).replace("'", "''")
                vals.append(f"'{s}'")
        out+=sep.join(vals)+newline
    return out

def format_json(columns, rows):
    data=[]
    for r in rows:
        obj={}
        for (col_name,_), v in zip(columns, r):
            obj[col_name]=v
        data.append(obj)
    if not data:
        return "[]\n"
    json_objs=[json.dumps(obj, separators=(',', ':')) for obj in data]
    return "[" + ",\n".join(json_objs) + "]\n"

def format_jsonlines(columns, rows):
    out=""
    for r in rows:
        obj={}
        for (col_name,_), v in zip(columns, r):
            obj[col_name]=v
        out+=json.dumps(obj, separators=(',', ':'))+"\n"
    return out

def format_insert(columns, rows, table_name="table", header=True):
    out=""
    for r in rows:
        vals=[]
        for v in r:
            if v is None:
                vals.append("NULL")
            elif isinstance(v,int):
                vals.append(str(v))
            elif isinstance(v,float):
                vals.append(str(v))
            else:
                s=str(v).replace("'", "''")
                vals.append(f"'{s}'")
        if header:
            cols="(" + ",".join([c[0] for c in columns]) + ")"
            out+=f"INSERT INTO {table_name}{cols} VALUES({','.join(vals)});\n"
        else:
            out+=f"INSERT INTO {table_name} VALUES({','.join(vals)});\n"
    return out

def format_tabs(columns, rows, header=True, nullvalue="NULL", newline="\n"):
    return format_list(columns, rows, header=header, sep="\t", newline=newline, nullvalue=nullvalue)

def format_tcl(columns, rows, header=True, nullvalue="NULL", newline="\n"):
    out=""
    if header:
        out+=" ".join([f'"{c[0]}"' for c in columns])+newline
    for r in rows:
        vals=[]
        for v in r:
            if v is None:
                vals.append(nullvalue)
            else:
                s=str(v).replace('"', '\\"')
                vals.append(f'"{s}"')
        out+=" ".join(vals)+newline
    return out

def format_trash(columns, rows):
    return ""

def format_result(columns, rows, mode, header, sep, newline, nullvalue, table_name="table"):
    if columns is None:
        return ""
    if mode=="duckbox":
        disp=[[nullvalue if v is None else v for v in r] for r in rows]
        return format_duckbox(columns, [[str(x) for x in row] for row in disp])
    elif mode=="box":
        disp=[[nullvalue if v is None else v for v in r] for r in rows]
        return format_box(columns, [[str(x) for x in row] for row in disp])
    elif mode=="table":
        disp=[[nullvalue if v is None else v for v in r] for r in rows]
        return format_table(columns, [[str(x) for x in row] for row in disp])
    elif mode=="column":
        disp=[[nullvalue if v is None else v for v in r] for r in rows]
        return format_column(columns, [[str(x) for x in row] for row in disp])
    elif mode=="csv":
        return format_csv(columns, rows, header=header, sep=sep, newline=newline, nullvalue=nullvalue)
    elif mode=="list":
        return format_list(columns, rows, header=header, sep=sep, newline=newline, nullvalue=nullvalue)
    elif mode=="markdown":
        return format_markdown(columns, rows, nullvalue=nullvalue)
    elif mode=="html":
        return format_html(columns, rows, header=header, nullvalue=nullvalue)
    elif mode=="line":
        return format_line(columns, rows, nullvalue=nullvalue)
    elif mode=="ascii":
        return format_ascii(columns, rows, header=header, nullvalue=nullvalue)
    elif mode=="quote":
        return format_quote(columns, rows, header=header, sep=sep, newline=newline, nullvalue=nullvalue)
    elif mode=="json":
        return format_json(columns, rows)
    elif mode=="jsonlines":
        return format_jsonlines(columns, rows)
    elif mode=="insert":
        return format_insert(columns, rows, table_name=table_name, header=header)
    elif mode=="tabs":
        return format_tabs(columns, rows, header=header, nullvalue=nullvalue, newline=newline)
    elif mode=="tcl":
        return format_tcl(columns, rows, header=header, nullvalue=nullvalue, newline=newline)
    elif mode=="trash":
        return ""
    else:
        return format_duckbox(columns, rows)

class DuckDBClone:
    def __init__(self, db_path, readonly=False):
        self.db_path=db_path
        self.readonly=readonly
        self.conn=None
        self.db_path_display=db_path
        self.open_db(db_path, readonly)

    def open_db(self, db_path, readonly=False):
        if self.conn:
            try:
                self.conn.close()
            except:
                pass
        self.db_path=db_path
        self.readonly=readonly
        if db_path==":memory:" or not db_path:
            self.conn=sqlite3.connect(":memory:")
            self.conn.row_factory=sqlite3.Row
            self.db_path_display=":memory:"
        else:
            if readonly and not os.path.exists(db_path):
                raise Exception(f'IO Error: Cannot open database "{db_path}" in read-only mode: database does not exist')
            if readonly:
                uri=f"file:{db_path}?mode=ro"
                self.conn=sqlite3.connect(uri, uri=True)
            else:
                d=os.path.dirname(db_path)
                if d and not os.path.exists(d):
                    os.makedirs(d, exist_ok=True)
                self.conn=sqlite3.connect(db_path)
            self.conn.row_factory=sqlite3.Row
            self.db_path_display=db_path

    def execute_sql(self, sql):
        import re
        # Preprocess :: cast
        def _replace_cast(s):
            pat=re.compile(r"""(['"][^'"]*['"]|\b\w+\b|\))\s*::\s*([A-Za-z_][A-Za-z0-9_\(\)]*(?:\([^)]*\))?)""", re.VERBOSE)
            def repl(m):
                expr=m.group(1)
                typ=m.group(2)
                return f"CAST({expr} AS {typ})"
            while "::" in s:
                ns,n=pat.subn(repl, s, count=1)
                if n==0:
                    break
                s=ns
            return s
        sql=_replace_cast(sql)

        # Special handling for DATE cast that sqlite mishandles
        # For SELECT CAST('2020-01-01' AS DATE) as d, we want to return date string with type date
        m_date = re.match(r"""\s*SELECT\s+CAST\s*\(\s*'([^']*)'\s+AS\s+DATE\s*\)(?:\s+as\s+(\w+))?\s*;?\s*$""", sql, re.IGNORECASE)
        if m_date:
            date_val=m_date.group(1)
            col_name=m_date.group(2) if m_date.group(2) else f"CAST('{date_val}' AS DATE)"
            # If without alias, DuckDB shows column name as CAST('2020-01-01' AS "DATE") ? We'll use provided or generic
            return [(col_name, "date")], [(date_val,)]

        # CSV
        m=re.match(r"""\s*SELECT\s+\*\s+FROM\s+['"]([^'"]+\.csv)['"]\s*;?\s*$""", sql, re.IGNORECASE)
        if m:
            return self.read_csv_as_result(m.group(1))
        m2=re.match(r"""\s*SELECT\s+\*\s+FROM\s+read_csv\s*\(\s*['"]([^'"]+)['"]""", sql, re.IGNORECASE)
        if m2:
            return self.read_csv_as_result(m2.group(1))
        # range
        m_range=re.match(r"""\s*SELECT\s+(.+?)\s+FROM\s+range\s*\(\s*(\d+)\s*\)\s*;?\s*$""", sql, re.IGNORECASE)
        if m_range:
            cols_expr=m_range.group(1).strip()
            n=int(m_range.group(2))
            if cols_expr=="*":
                col_name="range"
            else:
                m_alias=re.match(r"range\s+as\s+(\w+)", cols_expr, re.IGNORECASE)
                if m_alias:
                    col_name=m_alias.group(1)
                else:
                    col_name="range" if cols_expr.lower()=="range" else cols_expr.split()[0]
            return [(col_name, "int64")], [(i,) for i in range(n)]
        m_range2=re.match(r"""\s*SELECT\s+\*\s+FROM\s+range\s*\(\s*(\d+)\s*\)\s*;?\s*$""", sql, re.IGNORECASE)
        if m_range2:
            n=int(m_range2.group(1))
            return [("range", "int64")], [(i,) for i in range(n)]

        def infer_type_from_expr(expr):
            expr=expr.strip()
            pat=re.compile(r'\s+as\s+', re.IGNORECASE)
            matches=list(pat.finditer(expr))
            base=expr[:matches[-1].start()].strip() if matches else expr.strip()
            if re.match(r'^-?\d+$', base):
                try:
                    v=int(base)
                    return "int32" if -2**31 <= v <= 2**31-1 else "int64"
                except:
                    return "int32"
            if re.match(r'^-?\d+\.\d+$', base):
                s=base.lstrip('-')
                if '.' in s:
                    int_part,dec_part=s.split('.')
                    return f"decimal({len(int_part)+len(dec_part)},{len(dec_part)})"
            if re.match(r'^-?\d+(\.\d+)?[eE][+-]?\d+$', base):
                return "double"
            if re.match(r"^'.*'$", base) or re.match(r'^\".*\"$', base):
                return "varchar"
            if base.upper() in ("TRUE","FALSE"):
                return "boolean"
            if base.upper()=="NULL":
                return "int32"
            m_cast=re.match(r'CAST\s*\(.*\s+AS\s+"?([A-Za-z0-9_]+)"?\s*\)', base, re.IGNORECASE)
            if m_cast:
                typ=m_cast.group(1).upper()
                mapping={"BIGINT":"int64","INTEGER":"int32","INT":"int32","SMALLINT":"int16","DOUBLE":"double","FLOAT":"float","VARCHAR":"varchar","BOOLEAN":"boolean","DATE":"date"}
                return mapping.get(typ, typ.lower())
            if "range" in base.lower():
                return "int64"
            if "length" in base.lower():
                return "int64"
            if re.match(r'^[\d\s\+\-\*\/\(\)\.]+$', base):
                if '.' in base and re.search(r'\d+\.\d+', base):
                    return "decimal(12,1)"
                return "int32"
            return "varchar"

        cur=self.conn.cursor()
        try:
            cur.execute(sql)
            if cur.description is None:
                self.conn.commit()
                return None,None
            col_names=[desc[0] for desc in cur.description]
            rows=cur.fetchall()
            # Parse select exprs for type inference
            select_exprs=[]
            try:
                upper_sql=sql.upper()
                sel_idx=upper_sql.find("SELECT")
                from_idx=upper_sql.find(" FROM ")
                if sel_idx!=-1:
                    if from_idx!=-1:
                        select_part=sql[sel_idx+6:from_idx]
                    else:
                        select_part=sql[sel_idx+6:].strip().rstrip(';')
                    exprs=[]
                    cur_expr=""; paren=0; in_single=False; in_double=False
                    for ch in select_part:
                        if ch=="'" and not in_double:
                            in_single=not in_single
                            cur_expr+=ch
                            continue
                        if ch=='"' and not in_single:
                            in_double=not in_double
                            cur_expr+=ch
                            continue
                        if not in_single and not in_double:
                            if ch=='(':
                                paren+=1
                            elif ch==')':
                                paren-=1
                            elif ch==',' and paren==0:
                                exprs.append(cur_expr.strip())
                                cur_expr=""
                                continue
                        cur_expr+=ch
                    if cur_expr.strip():
                        exprs.append(cur_expr.strip())
                    select_exprs=exprs
            except:
                select_exprs=[]
            columns=[]
            for idx,name in enumerate(col_names):
                col_type=None
                if idx < len(select_exprs):
                    try:
                        col_type=infer_type_from_expr(select_exprs[idx])
                    except:
                        col_type=None
                if col_type is None:
                    col_type="int32"
                    found=False
                    for r in rows:
                        v=r[idx]
                        if v is None:
                            continue
                        if isinstance(v,int):
                            col_type="int32" if -2**31 <= v <= 2**31-1 else "int64"
                            found=True
                            break
                        elif isinstance(v,float):
                            col_type="double"
                            found=True
                            break
                        elif isinstance(v,str):
                            col_type="varchar"
                            found=True
                            break
                    if not found:
                        col_type="int32"
                columns.append((name, col_type))
            py_rows=[]
            for r in rows:
                py_rows.append([r[i] for i in range(len(col_names))])
            return columns, py_rows
        except sqlite3.OperationalError as e:
            msg=str(e)
            if "no such table" in msg.lower():
                m_tbl=re.search(r"no such table:\s*(\S+)", msg, re.IGNORECASE)
                tbl=m_tbl.group(1) if m_tbl else "unknown"
                raise Exception(f'Catalog Error: Table with name {tbl} does not exist!\nDid you mean "pg_tables"?\n\nLINE 1: {sql}')
            else:
                raise Exception(msg)
        except Exception as e:
            raise e

    def read_csv_as_result(self, csv_path):
        if not os.path.exists(csv_path):
            raise Exception(f'IO Error: No files found that match the pattern "{csv_path}"\n\nLINE 1: SELECT * FROM \'{csv_path}\'\n                      ^')
        with open(csv_path, newline='', encoding='utf-8') as f:
            reader=csv.reader(f)
            try:
                header=next(reader)
            except StopIteration:
                header=[]
            rows=[]
            for row in reader:
                conv=[]
                for val in row:
                    if val=="":
                        conv.append("")
                    else:
                        try:
                            conv.append(int(val))
                        except:
                            try:
                                conv.append(float(val))
                            except:
                                conv.append(val)
                rows.append(conv)
            columns=[]
            for idx,name in enumerate(header):
                col_type="varchar"
                for r in rows:
                    if idx < len(r):
                        v=r[idx]
                        if isinstance(v,int):
                            col_type="int64"
                            break
                        elif isinstance(v,float):
                            col_type="double"
                            break
                columns.append((name, col_type))
            return columns, rows

    def get_tables(self, pattern=None):
        cur=self.conn.cursor()
        if pattern:
            cur.execute("SELECT name FROM sqlite_master WHERE type='table' AND name LIKE ?", (pattern,))
        else:
            cur.execute("SELECT name FROM sqlite_master WHERE type='table'")
        tables=[r[0] for r in cur.fetchall()]
        result=[]
        for tbl in tables:
            cur.execute(f"PRAGMA table_info('{tbl}')")
            cols=cur.fetchall()
            col_infos=[(c[1], (c[2].lower() if c[2] else "integer")) for c in cols]
            try:
                cur.execute(f'SELECT COUNT(*) FROM "{tbl}"')
                cnt=cur.fetchone()[0]
            except:
                cnt=0
            result.append((tbl, col_infos, cnt))
        return result

    def get_databases(self):
        if self.db_path_display==":memory:":
            return [("memory", "(memory)")]
        else:
            base=os.path.basename(self.db_path_display)
            name_no_ext=os.path.splitext(base)[0]
            return [(name_no_ext, self.db_path_display)]

class ShellState:
    def __init__(self, db_path, readonly=False):
        self.db=DuckDBClone(db_path, readonly=readonly)
        self.mode="duckbox"
        self.header=True
        self.separator="|"
        self.newline="\n"
        self.nullvalue="NULL"
        self.echo=False
        self.bail=False
        self.timer=False
        self.changes=False
        self.output_file=None
        self.output_path="stdout"
        self.once_path=None
        self.maxrows=40
        self.maxwidth=0
        self.widths=[]
        self.insert_table="table"

def do_show(state):
    def display_sep(s):
        if s=="\n":
            return r'"\n"'
        elif s=="\r\n":
            return r'"\r\n"'
        elif s=="\r":
            return r'"\r"'
        elif s=="\t":
            return r'"\t"'
        elif s=="\x1f":
            return r'"\037"'
        elif s=="\x1e":
            return r'"\036"'
        elif s==" ":
            return r'" "'
        else:
            return f'"{s}"'
    def fmt(label,val):
        return f"{label:>12}: {val}"
    lines=[]
    lines.append(fmt("echo", "on" if state.echo else "off"))
    lines.append(fmt("headers", "on" if state.header else "off"))
    lines.append(fmt("mode", state.mode))
    lines.append(fmt("nullvalue", f'"{state.nullvalue}"'))
    lines.append(fmt("output", state.output_path))
    lines.append(fmt("colseparator", display_sep(state.separator)))
    lines.append(fmt("rowseparator", display_sep(state.newline)))
    lines.append(fmt("width", ""))
    lines.append(fmt("filename", state.db.db_path_display))
    return "\n".join(lines)+"\n"

def do_version(state):
    return VERSION_DOT

def do_about(state):
    return ABOUT_STR

def do_help(state, args):
    try:
        if os.path.exists("/tmp/help_short.txt"):
            short=open("/tmp/help_short.txt","r",encoding="utf-8").read()
            allh=open("/tmp/help_all.txt","r",encoding="utf-8").read()
            if not args:
                return short
            if args[0]=="--all":
                return allh
            else:
                return f"Nothing matches '{args[0]}'\n"
    except:
        pass
    if not args:
        GREEN="\x1b[32m"; YELLOW="\x1b[33m"; RESET="\x1b[00m"
        lines=[]
        cmds=[
            (".about","", "Show information about DuckDB"),
            (".bail","on|off","Stop after hitting an error.  Default OFF"),
            (".binary","on|off","Turn binary output on or off.  Default OFF"),
            (".cd","DIRECTORY","Change the working directory to DIRECTORY"),
            (".changes","on|off","Show number of rows changed by SQL"),
            (".show","","Show the current values for various settings"),
            (".tables","?TABLE?","List names of tables matching LIKE pattern TABLE"),
            (".version","","Show the version"),
        ]
        for cmd,arg,desc in cmds:
            if arg:
                lines.append(f"{GREEN}{cmd}{RESET}{YELLOW} {arg}{RESET}  {desc}")
            else:
                lines.append(f"{GREEN}{cmd}{RESET}  {desc}")
        return "\n".join(lines)+"\n"
    if args[0]=="--all":
        return do_help(state, [])
    return f"Nothing matches '{args[0]}'\n"

def handle_dot_command(state, line):
    if not line.startswith('.'):
        return None, False, False
    content=line[1:].strip()
    if not content:
        return "Invalid Command Error: Invalid usage of command '.'\n\nUsage: '.help'\n", True, False
    parts=content.split()
    if not parts:
        return "Invalid Command Error: Invalid usage of command '.'\n\nUsage: '.help'\n", True, False
    cmd=parts[0].lower()
    args=parts[1:]

    if cmd=="print":
        idx=line.lower().find('.print')
        rest=line[idx+len('.print'):].lstrip()
        return rest+"\n", False, False
    if cmd=="about":
        if args:
            return f"Invalid Command Error: Invalid usage of command '.about'\n\nUsage: '.about '\n", True, False
        return ABOUT_STR, False, False
    if cmd=="version":
        if args:
            return f"Invalid Command Error: Invalid usage of command '.version'\n\nUsage: '.version '\n", True, False
        return VERSION_DOT, False, False
    if cmd=="show":
        if args:
            return f"Invalid Command Error: Invalid usage of command '.show'\n\nUsage: '.show '\n", True, False
        return do_show(state), False, False
    if cmd=="help":
        return do_help(state, args), False, False
    if cmd=="quit":
        if len(args)>1:
            return f"Invalid Command Error: Invalid usage of command '.quit'\n\nUsage: '.quit ?CODE?'\n", True, False
        sys.exit(0)
    if cmd=="exit":
        if len(args)>1:
            return f"Invalid Command Error: Invalid usage of command '.exit'\n\nUsage: '.exit ?CODE?'\n", True, False
        if args:
            try:
                code=int(args[0])
                sys.exit(code)
            except:
                return f"Invalid Command Error: Invalid usage of command '.exit'\n\nUsage: '.exit ?CODE?'\n", True, False
        else:
            sys.exit(0)
    if cmd=="mode":
        if len(args)==0:
            return f"current output mode: {state.mode}\n", False, False
        if len(args)>2:
            return f"Invalid Command Error: Invalid usage of command '.mode'\n\nUsage: '.mode MODE ?TABLE?'\n", True, False
        mode_arg=args[0]
        valid_modes=["ascii","box","column","csv","duckbox","html","insert","json","jsonlines","latex","line","list","markdown","quote","table","tabs","tcl","trash"]
        if mode_arg not in valid_modes:
            return f"Error: mode should be one of: {' '.join(valid_modes)} \n", True, False
        if len(args)==2 and mode_arg!="insert":
            return f"TABLE argument can only be used with .mode insert\n", True, False
        state.mode=mode_arg
        if mode_arg=="csv":
            state.separator=","; state.newline="\r\n"
        elif mode_arg=="quote":
            state.separator=","; state.newline="\n"
        elif mode_arg=="ascii":
            state.separator="\x1f"; state.newline="\x1e"
        elif mode_arg=="tabs":
            state.separator="\t"; state.newline="\n"
        elif mode_arg=="tcl":
            state.separator=" "; state.newline="\n"
        else:
            state.separator="|"; state.newline="\n"
        state.insert_table=args[1] if len(args)==2 else "table"
        return "", False, False
    if cmd=="headers":
        if len(args)!=1:
            return f"Invalid Command Error: Invalid usage of command '.headers'\n\nUsage: '.headers on|off'\n", True, False
        v=args[0].lower()
        if v=="on":
            state.header=True; return "", False, False
        elif v=="off":
            state.header=False; return "", False, False
        else:
            return f"Invalid Command Error: Invalid usage of command '.headers'\n\nUsage: '.headers on|off'\n", True, False
    if cmd=="separator":
        if len(args)==0:
            return f"Invalid Command Error: Invalid usage of command '.separator'\n\nUsage: '.separator COL ?ROW?'\n", True, False
        if len(args)>2:
            return f"Invalid Command Error: Invalid usage of command '.separator'\n\nUsage: '.separator COL ?ROW?'\n", True, False
        def unquote(s):
            if len(s)>=2 and ((s[0]=='"' and s[-1]=='"') or (s[0]=="'" and s[-1]=="'")):
                return s[1:-1]
            return s
        state.separator=parse_sep(unquote(args[0]))
        if len(args)==2:
            state.newline=parse_sep(unquote(args[1]))
        return "", False, False
    if cmd=="nullvalue":
        if len(args)!=1:
            return f"Invalid Command Error: Invalid usage of command '.nullvalue'\n\nUsage: '.nullvalue STRING'\n", True, False
        arg=args[0]
        if arg=="''" or arg=='""':
            state.nullvalue=""
        else:
            if len(arg)>=2 and ((arg[0]=="'" and arg[-1]=="'") or (arg[0]=='"' and arg[-1]=='"')):
                state.nullvalue=arg[1:-1]
            else:
                state.nullvalue=arg
        return "", False, False
    if cmd=="bail":
        if len(args)!=1:
            return f"Invalid Command Error: Invalid usage of command '.bail'\n\nUsage: '.bail on|off'\n", True, False
        v=args[0].lower()
        if v=="on":
            state.bail=True; return "", False, False
        elif v=="off":
            state.bail=False; return "", False, False
        else:
            return f"Invalid Command Error: Invalid usage of command '.bail'\n\nUsage: '.bail on|off'\n", True, False
    if cmd=="timer":
        if len(args)!=1:
            return f"Invalid Command Error: Invalid usage of command '.timer'\n\nUsage: '.timer on|off'\n", True, False
        v=args[0].lower()
        if v in ("on","off"):
            state.timer=(v=="on"); return "", False, False
        else:
            return f"Invalid Command Error: Invalid usage of command '.timer'\n\nUsage: '.timer on|off'\n", True, False
    if cmd=="echo":
        if len(args)!=1:
            return f"Invalid Command Error: Invalid usage of command '.echo'\n\nUsage: '.echo on|off'\n", True, False
        v=args[0].lower()
        if v=="on":
            state.echo=True; return "", False, False
        elif v=="off":
            state.echo=False; return "", False, False
        else:
            return f"Invalid Command Error: Invalid usage of command '.echo'\n\nUsage: '.echo on|off'\n", True, False
    if cmd=="changes":
        if len(args)!=1:
            return f"Invalid Command Error: Invalid usage of command '.changes'\n\nUsage: '.changes on|off'\n", True, False
        v=args[0].lower()
        if v in ("on","off"):
            state.changes=(v=="on"); return "", False, False
        else:
            return f"Invalid Command Error: Invalid usage of command '.changes'\n\nUsage: '.changes on|off'\n", True, False
    if cmd=="output":
        if len(args)==0:
            if state.output_file and state.output_file!=sys.stdout:
                try:
                    state.output_file.close()
                except:
                    pass
            state.output_file=None; state.output_path="stdout"
            return "", False, False
        if len(args)>1:
            return f'ERROR: extra parameter: "{args[1]}".  Usage:\n\x1b[32m.output\x1b[00m\x1b[33m ?FILE?\x1b[00m    Send output to FILE or stdout if FILE is omitted\n  If FILE begins with \'|\' then open as a pipe\n\x1b[33m    --bom\x1b[00m         Put a UTF8 byte-order mark at the beginning\n\x1b[33m    -e\x1b[00m            Send output to the system text editor\n\x1b[33m    -x\x1b[00m            Send output as CSV to a spreadsheet (same as ".excel")\n', True, False
        file_arg=args[0]
        if file_arg=="stdout":
            if state.output_file and state.output_file!=sys.stdout:
                try:
                    state.output_file.close()
                except:
                    pass
            state.output_file=None; state.output_path="stdout"
            return "", False, False
        try:
            if state.output_file and state.output_file!=sys.stdout:
                try:
                    state.output_file.close()
                except:
                    pass
            f=open(file_arg,'w',encoding='utf-8')
            state.output_file=f; state.output_path=file_arg
            return "", False, False
        except:
            return f"Error: cannot open \"{file_arg}\"\n", True, False
    if cmd=="once":
        if len(args)==0:
            return f"Invalid Command Error: Invalid usage of command '.once'\n\nUsage: '.once ?FILE?'\n", True, False
        if len(args)>1:
            return f'ERROR: extra parameter: "{args[1]}".  Usage:\n', True, False
        state.once_path=args[0]
        return "", False, False
    if cmd=="open":
        opts=[]; file_arg=None
        for a in args:
            if a.startswith('--'):
                opts.append(a)
            else:
                file_arg=a
        readonly="--readonly" in opts
        new="--new" in opts
        if file_arg is None:
            file_arg=":memory:"
        if new:
            try:
                if os.path.exists(file_arg):
                    os.remove(file_arg)
            except:
                pass
        try:
            state.db.open_db(file_arg, readonly=readonly)
            return "", False, False
        except Exception as e:
            return f"{e}\n", True, False
    if cmd=="cd":
        if len(args)!=1:
            return f"Invalid Command Error: Invalid usage of command '.cd'\n\nUsage: '.cd DIRECTORY'\n", True, False
        try:
            os.chdir(args[0])
            return "", False, False
        except:
            return f"Error: cannot change directory to \"{args[0]}\"\n", True, False
    if cmd=="read":
        if len(args)!=1:
            return f"Invalid Command Error: Invalid usage of command '.read'\n\nUsage: '.read FILE'\n", True, False
        return f"__READ_FILE__:{args[0]}", False, True
    if cmd=="tables":
        if len(args)>1:
            return f"Invalid Command Error: Invalid usage of command '.tables'\n\nUsage: '.tables ?TABLE?'\n", True, False
        pat=args[0] if args else None
        tables_info=state.db.get_tables(pat)
        if not tables_info:
            return "", False, False
        out=""
        for tbl_name,col_infos,cnt in tables_info:
            col_strs=[f"{n} {t}" for n,t in col_infos]
            max_len=len(tbl_name)
            for s in col_strs:
                max_len=max(max_len, len(s))
            row_str=f"{cnt} rows"
            max_len=max(max_len, len(row_str))
            width=max_len+2
            out+=f"┌{'─'*width}┐\n"
            out+=f"│{tbl_name.center(width)}│\n"
            out+=f"│{' '*width}│\n"
            for cs in col_strs:
                out+=f"│{' '+cs.ljust(width-1)}│\n"
            out+=f"│{' '*width}│\n"
            out+=f"│{row_str.center(width)}│\n"
            out+=f"└{'─'*width}┘\n"
        return out, False, False
    if cmd=="schema":
        if len(args)>1:
            return f"Invalid Command Error: Invalid usage of command '.schema'\n\nUsage: '.schema ?PATTERN?'\n", True, False
        pat=args[0] if args else None
        cur=state.db.conn.cursor()
        if pat:
            cur.execute("SELECT sql FROM sqlite_master WHERE type='table' AND name LIKE ?", (pat,))
        else:
            cur.execute("SELECT sql FROM sqlite_master WHERE type='table'")
        out=""
        for r in cur.fetchall():
            sql=r[0]
            if sql:
                out+=sql+";\n"
        return out, False, False
    if cmd=="databases":
        if args:
