    known=["about","auto_format","bail","binary","cd","changes","columns","decimal_sep","databases","dump","display_colors","echo","edit","excel","exit","headers","help","highlight","highlight_colors","highlight_errors","highlight_mode","highlight_results","import","indexes","last","large_number_rendering","log","maxrows","maxwidth","mode","multiline","nullvalue","open","once","output","pager","print","progress_bar","prompt","quit","read","read_line_version","render_completion","render_errors","rows","safe_mode","separator","schema","shell","show","singleline","startup_text","system","tables","thousand_sep","timer","ui_command","version","width"]
