def execute_and_format(state, sql, output_handle):
    stmts=split_sql_statements(sql)
    had_error=False
    for stmt in stmts:
        if not stmt.strip():
            continue
        if state.echo:
            output_handle.write(stmt+"\n")
        import time
        start=time.time()
        try:
            columns, rows = state.db.execute_sql(stmt)
            if columns is None and rows is None:
                if state.changes:
                    total=state.db.conn.total_changes
                    output_handle.write(f"changes:   1   total_changes: {total}\n")
                if state.timer:
                    elapsed=time.time()-start
                    output_handle.write(f"Run Time (s): real {elapsed:.3f} user 0.000000 sys 0.000000\n")
            else:
                formatted=format_result(columns, rows, state.mode, state.header, state.separator, state.newline, state.nullvalue, table_name=state.insert_table)
                output_handle.write(formatted)
                if state.timer:
                    elapsed=time.time()-start
                    output_handle.write(f"Run Time (s): real {elapsed:.3f} user 0.000000 sys 0.000000\n")
        except Exception as e:
            sys.stderr.write(str(e)+"\n")
            had_error=True
            if state.bail:
                break
    return had_error

def split_sql_statements(sql_buffer):
    statements=[]; current=[]; in_single=False; in_double=False; in_block=False
    i=0
    while i < len(sql_buffer):
        c=sql_buffer[i]
        if not in_single and not in_double:
            if not in_block and sql_buffer[i:i+2]=="/*":
                in_block=True
                current.append(c); i+=1
                if i < len(sql_buffer):
                    current.append(sql_buffer[i])
                i+=1; continue
            if in_block and sql_buffer[i:i+2]=="*/":
                in_block=False
                current.append(c); i+=1
                if i < len(sql_buffer):
                    current.append(sql_buffer[i])
                i+=1; continue
            if in_block:
                current.append(c); i+=1; continue
        if not in_single and not in_double and not in_block:
            if sql_buffer[i:i+2]=="--":
                while i < len(sql_buffer) and sql_buffer[i]!='\n':
                    current.append(sql_buffer[i]); i+=1
                if i < len(sql_buffer):
                    current.append(sql_buffer[i]); i+=1
                continue
        if c=="'" and not in_double and not in_block:
            if in_single and i+1 < len(sql_buffer) and sql_buffer[i+1]=="'":
                current.append(c); current.append(sql_buffer[i+1]); i+=2; continue
            else:
                in_single=not in_single; current.append(c); i+=1; continue
        if c=='"' and not in_single and not in_block:
            if in_double and i+1 < len(sql_buffer) and sql_buffer[i+1]=='"':
                current.append(c); current.append(sql_buffer[i+1]); i+=2; continue
            else:
                in_double=not in_double; current.append(c); i+=1; continue
        if c==';' and not in_single and not in_double and not in_block:
            current.append(c)
            stmt="".join(current).strip()
            if stmt:
                statements.append(stmt)
            current=[]; i+=1; continue
        else:
            current.append(c); i+=1
    leftover="".join(current).strip()
    if leftover:
        statements.append(leftover)
    return statements

def process_input(state, input_text, output_handle=sys.stdout, is_file=False):
    sql_buffer=""; had_error=False
    lines=input_text.splitlines(keepends=True)
    for line in lines:
        if line.startswith('.') and sql_buffer.strip()=="":
            dot_line=line.rstrip('\r\n')
            # Skip output/once from once redirect?
            result, is_error, is_read = handle_dot_command(state, dot_line)
            if isinstance(result, str) and result.startswith("__READ_FILE__:"):
                fp=result.split(":",1)[1]
                try:
                    with open(fp,'r',encoding='utf-8') as ff:
                        fc=ff.read()
                    err=process_input(state, fc, output_handle=output_handle, is_file=True)
                    if err:
                        had_error=True
                        if state.bail:
                            break
                except:
                    sys.stderr.write(f"Error: cannot open \"{fp}\"\n")
                    had_error=True
                    if state.bail:
                        break
                continue
            if result is None:
                continue
            # If this dot command itself is .once or .output, don't treat its empty output as redirect target
            is_output_cmd = dot_line.lower().startswith('.once') or dot_line.lower().startswith('.output')
            if is_error:
                sys.stderr.write(result)
                had_error=True
                if state.bail:
                    break
            else:
                if not is_output_cmd and state.once_path:
                    try:
                        once_f=open(state.once_path,'w',encoding='utf-8')
                        once_f.write(result)
                        once_f.close()
                    except:
                        pass
                    state.once_path=None
                    continue
                if state.output_file:
                    state.output_file.write(result)
                else:
                    output_handle.write(result)
            continue
        else:
            sql_buffer+=line
            if ';' in sql_buffer:
                stmts=split_sql_statements(sql_buffer)
                if sql_buffer.strip().endswith(';'):
                    to_exec=stmts
                    sql_buffer=""
                else:
                    to_exec=stmts[:-1]
                    sql_buffer=stmts[-1] if stmts else ""
                for stmt in to_exec:
                    out_handle=output_handle
                    once_active=False
                    if state.once_path:
                        try:
                            out_handle=open(state.once_path,'w',encoding='utf-8')
                            once_active=True
                        except:
                            out_handle=output_handle
                    elif state.output_file:
                        out_handle=state.output_file
                    had_err=execute_and_format(state, stmt, out_handle)
                    if once_active:
                        out_handle.close()
                        state.once_path=None
                    if had_err:
                        had_error=True
                        if state.bail:
                            sql_buffer=""
                            break
                if had_error and state.bail:
                    break
    if sql_buffer.strip()!="":
        if sql_buffer.strip().startswith('.'):
            for dot_line in sql_buffer.strip().splitlines():
                dot_line=dot_line.strip()
                if not dot_line:
                    continue
                if dot_line.startswith('.'):
                    result, is_error, is_read = handle_dot_command(state, dot_line)
                    if isinstance(result, str) and result.startswith("__READ_FILE__:"):
                        fp=result.split(":",1)[1]
                        try:
                            with open(fp,'r',encoding='utf-8') as ff:
                                fc=ff.read()
                            err=process_input(state, fc, output_handle=output_handle, is_file=True)
                            if err:
                                had_error=True
                        except:
                            sys.stderr.write(f"Error: cannot open \"{fp}\"\n")
                            had_error=True
                        continue
                    is_output_cmd = dot_line.lower().startswith('.once') or dot_line.lower().startswith('.output')
                    if is_error:
                        sys.stderr.write(result)
                        had_error=True
                        if state.bail:
                            break
                    else:
                        if not is_output_cmd and state.once_path:
                            try:
                                once_f=open(state.once_path,'w',encoding='utf-8')
                                once_f.write(result)
                                once_f.close()
                            except:
                                pass
                            state.once_path=None
                        else:
                            if state.output_file:
                                state.output_file.write(result)
                            else:
                                output_handle.write(result)
        else:
            out_handle=output_handle
            once_active=False
            if state.once_path:
                try:
                    out_handle=open(state.once_path,'w',encoding='utf-8')
                    once_active=True
                except:
                    out_handle=output_handle
            elif state.output_file:
                out_handle=state.output_file
            had_err=execute_and_format(state, sql_buffer, out_handle)
            if once_active:
                out_handle.close()
                state.once_path=None
            if had_err:
                had_error=True
    return had_error

