                with open(val,'r',encoding='utf-8') as ff:
                    content=ff.read()
                err=process_input(shell, content, output_handle=sys.stdout, is_file=True)
                if err:
                    had_error=True
                    if shell.bail:
                        break
            except FileNotFoundError:
                sys.stderr.write(f"Error: cannot open \"{val}\"\n")
                had_error=True
                if shell.bail:
                    break

    for sql in sql_positional:
        if sql.startswith('.'):
            result, is_error, is_read = handle_dot_command(shell, sql)
            if isinstance(result, str) and result.startswith("__READ_FILE__:"):
                fp=result.split(":",1)[1]
                try:
                    with open(fp,'r',encoding='utf-8') as ff:
                        fc=ff.read()
                    err=process_input(shell, fc, output_handle=sys.stdout, is_file=True)
                    if err:
                        had_error=True
                except:
                    sys.stderr.write(f"Error: cannot open \"{fp}\"\n")
                    had_error=True
                continue
            is_output_cmd = sql.lower().startswith('.once') or sql.lower().startswith('.output')
            if is_error:
                sys.stderr.write(result)
                had_error=True
                if shell.bail:
                    break
            else:
                if not is_output_cmd and shell.once_path:
                    try:
                        once_f=open(shell.once_path,'w',encoding='utf-8')
                        once_f.write(result)
                        once_f.close()
                    except:
                        pass
                    shell.once_path=None
                else:
                    if shell.output_file:
                        shell.output_file.write(result)
                    else:
                        sys.stdout.write(result)
        else:
            out_handle=sys.stdout
            if shell.once_path:
                try:
                    out_handle=open(shell.once_path,'w',encoding='utf-8')
                except:
                    out_handle=sys.stdout
            elif shell.output_file:
                out_handle=shell.output_file
            had_err=execute_and_format(shell, sql, out_handle)
            if out_handle!=sys.stdout and out_handle!=shell.output_file:
                out_handle.close()
                shell.once_path=None
            if had_err:
                had_error=True
                if shell.bail:
                    break

    has_batch=len(state_opts["c_cmds"])>0 or len(state_opts["f_files"])>0 or len(sql_positional)>0
    if not has_batch and not state_opts["no_stdin"]:
        is_tty=sys.stdin.isatty()
        if state_opts["interactive"] or is_tty:
            sys.stdout.write(VERSION_DOT)
            sys.stdout.write("\x1b[90mEnter \".help\" for usage hints.\n\x1b[00m")
        stdin_content=sys.stdin.read()
        if stdin_content.strip()!="":
            err=process_input(shell, stdin_content, output_handle=sys.stdout, is_file=False)
            if err:
                had_error=True

    sys.exit(1 if had_error else 0)

if __name__=="__main__":
    main()
